async function validateGraph(){const r=await api('/graph/preflight',{method:'POST',body:{graph:state.graph}});state.check=r;state.bottom='copilot';renderInspector();renderBottom();toast(r.ok?'Preflight passed · '+duration(r.reservation_cpu_seconds)+' worst-case CPU reservation':r.issues.length+' checks need attention',!r.ok);return r;}
async function runPipeline(){const checked=await validateGraph();if(!checked.ok)return;const estimate=await api('/operations/estimate',{method:'POST',body:{graph:state.graph}});const outputControl=estimate.allowance.access==='research-pro'?'<label class="field">Maximum new retained outputs · MiB<input id="runOutputLimit" type="number" min="1" step="1" max="'+Math.floor(estimate.remaining.storage_bytes/1048576)+'" value="'+Math.floor((state.graph.maximum_output_bytes??estimate.remaining.storage_bytes)/1048576)+'"><small>This is an explicit output ceiling. Exceeding it fails publication; scientific inputs are never reduced. Reserve part of your remaining capacity to permit uploads or concurrent jobs.</small></label>':'';const accepted=await new Promise(resolve=>{openModal('Review execution allowance',`<p>Conservative maximum cost reservation: <strong>$${Number(estimate.estimate?.pretax_usd||0).toFixed(4)} before tax</strong>.</p><p>${esc(estimate.allowance.label)} · ${duration(checked.reservation_cpu_seconds)} maximum allocated CPU time. Queue and image startup can add delay. The workflow runs on the full selected inputs.</p><p>Remaining spending allowance: $${Number(estimate.remaining?.budget_usd||0).toFixed(2)}. ${estimate.fits_allowance?'This estimate fits the remaining allowance.':'This estimate does not fit the current allowance; submission will remain blocked.'}</p>${outputControl}<div class="action-row"><button id="confirmExecution" class="button primary">Start workflow</button><button id="cancelExecution" class="button quiet">Keep editing</button></div>`);const dialog=$('#modal');dialog.addEventListener('close',()=>resolve(false),{once:true});const outputField=$('#runOutputLimit');const refreshFit=()=>{$('#confirmExecution').disabled=outputField?!(estimate.compute_fits&&outputField.checkValidity()):!estimate.fits_allowance;};outputField?.addEventListener('input',refreshFit);refreshFit();$('#confirmExecution').onclick=()=>{const field=$('#runOutputLimit');if(field){if(!field.reportValidity())return;state.graph.maximum_output_bytes=Number(field.value)*1048576;}resolve(true);dialog.close();};$('#cancelExecution').onclick=()=>dialog.close();});if(!accepted)return;await saveGraph();$('#runButton').disabled=true;try{const r=await api('/runs',{method:'POST',headers:{'Idempotency-Key':uid('op_')},body:{graph:state.graph}});state.run=r.run;state.logs=[];state.statuses.clear();canvas.status=state.statuses;state.outputs=[];setBottom('execution');watchRun(r.run.id);await refreshSession();}finally{$('#runButton').disabled=false;}}
function watchRun(rid){state.source?.close();const source=new EventSource('/api/runs/'+rid+'/events');state.source=source;$('#stopButton').disabled=['succeeded','failed','cancelled','interrupted'].includes(state.run?.state);$('#connectionStatus').textContent='Execution stream connected';source.onmessage=e=>{const event=JSON.parse(e.data),p=event.payload;if(event.kind==='run.state'){state.run={...state.run,...p};if(p.state==='running')$('#runButton').disabled=true;}if(event.kind==='task.state'){const old=state.statuses.get(event.node_id)||{};state.statuses.set(event.node_id,{...old,...p});canvas.invalidate();}if(event.kind==='task.metrics'){const old=state.statuses.get(event.node_id)||{};state.statuses.set(event.node_id,{...old,metrics:p});}if(event.kind==='log'||p.error){state.logs.push(event);if(state.logs.length>2000)state.logs.splice(0,state.logs.length-2000);}clearTimeout(logRenderTimer);logRenderTimer=setTimeout(()=>{if(['logs','execution'].includes(state.bottom))renderBottom();},90);};source.addEventListener('complete',guarded(async()=>{source.close();$('#stopButton').disabled=true;$('#runButton').disabled=false;$('#connectionStatus').textContent='Workspace connected';await loadRun(rid,false);await refreshSession();toast(state.run.state==='succeeded'?'Pipeline completed · '+state.outputs.length+' artifacts published':state.run.error||state.run.state,state.run.state!=='succeeded');}));source.onerror=()=>{$('#connectionStatus').textContent='Reconnecting execution stream…';};}
async function loadRun(rid,replay=true){const r=await api('/runs/'+rid);state.run=r.run;state.outputs=r.artifacts;state.attempts=r.attempts;state.statuses.clear();for(const a of r.attempts)state.statuses.set(a.node_id,{state:a.state,metrics:{...a.metrics,elapsed_seconds:a.metrics?.elapsed_seconds??a.metrics?.seconds},error:a.error});canvas.status=state.statuses;canvas.invalidate();if(replay){state.logs=[];watchRun(rid);}renderBottom();}
