function showTemplates(){const groups=[['Curated samples','curated-sample'],['Research blueprints','research-blueprint']];openModal('Choose a workflow',groups.map(([label,kind])=>`<section class="template-section"><h3>${label}</h3><p class="tiny">${kind==='curated-sample'?'Provided inputs; bounded cloud execution.':'Bind your cloud data and review resource estimates before running.'}</p><div class="template-grid">${state.templates.filter(t=>(t.kind||(t.access==='explore'?'curated-sample':'research-blueprint'))===kind).map(t=>`<button class="template-card" data-template="${esc(t.id)}"><h3>${esc(t.name)}</h3><span class="badge">${kind==='curated-sample'?'Sample workflow':'Needs input binding'}</span><p>${esc(t.description)}</p><small>${t.graph.nodes.length} nodes · ${t.graph.edges.length} connections${t.required_bindings?.length?' · '+t.required_bindings.length+' input bindings':''}</small><small>${t.validation_state==='sample-run-verified'?'Sample execution verified':'Representative validation pending'}</small></button>`).join('')}</div></section>`).join(''),'PIPELINE TEMPLATES');modalClick('[data-template]',async(e,b)=>{await saveGraph();const t=state.templates.find(t=>t.id===b.dataset.template);replaceGraph(t.graph);state.run=null;state.outputs=[];state.logs=[];closeModal();renderBottom();});}
