async function showToolRights(id){
 const spec=state.defs.get(id);if(!spec)return;state.settings=await api('/settings');const approved=state.settings.rights_approved.includes(id),canReview=state.user.role==='admin';
 openModal(spec.name+' · permission',`<div class="action-row"><span class="badge">${esc(spec.license)}</span><span class="badge">${approved?'Permission recorded':'Review needed'}</span></div>${spec.docs?`<p><a href="${esc(spec.docs)}" target="_blank" rel="noopener noreferrer">Provider documentation and terms ↗</a></p>`:''}<p>${esc(spec.rights_note||'Confirm your organization is authorized for this software and intended use.')}</p>${canReview?`<label class="field">Terms or agreement reference<input id="toolTerms" type="url" value="${esc(spec.docs||'')}" placeholder="https://provider/terms"></label><label class="field">Authorization basis<textarea id="toolPermissionReason" rows="2" minlength="10" placeholder="Institution, intended use, and permission basis"></textarea></label><label class="toggle-label"><input id="toolPermissionConfirm" type="checkbox">I confirm authorization for this tool and intended use</label><div class="action-row"><button id="recordToolPermission" class="button primary">Record permission</button>${approved?'<button id="revokeToolPermission" class="button danger">Revoke permission</button>':''}</div>`:'<p>Your administrator can record the applicable permission.</p>'}<p class="tiny">Compute allowance, dataset rights, runtime availability and API credentials are checked separately.</p>`,'TOOL PERMISSION');
 const save=async approved=>{await api('/admin/tool-rights/'+encodeURIComponent(state.user.id)+'/'+encodeURIComponent(id),{method:'POST',body:{approved,confirm_authorization:$('#toolPermissionConfirm').checked,terms_url:$('#toolTerms').value,reason:$('#toolPermissionReason').value}});await loadCatalogue();closeModal();renderInspector();toast(approved?'Tool permission recorded':'Tool permission revoked');};modalClick('#recordToolPermission',()=>save(true));modalClick('#revokeToolPermission',()=>save(false));
}

function settingsTabs(tab){return `<nav class="tabs">${[['general','General'],['trust','Cloud & allowance'],['vault','Vault'],['retention','Retention'],['credits','Data credits']].map(([id,label])=>`<button data-settings-tab="${id}" class="${tab===id?'active':''}">${label}</button>`).join('')}</nav>`;}

async function showSettings(tab='general'){if(['data','trust'].includes(tab)){$('#cloudOperationsButton').click();return;}state.settings=await api('/settings');await refreshAssets();const s=state.settings;let html=settingsTabs(tab),retentionData;
 if(tab==='retention'){retentionData=await api('/operations/retention');html+=retentionMarkup(retentionData);}
 if(tab==='credits'){const pages=await Promise.all([api('/assets?family=hpo&q=hpo&limit=100'),api('/assets?family=clinvar&q=clinvar&release=2026-06-27&limit=100')]),credits=resourceCredits(pages.flatMap(p=>p.assets));html+=`<p class="tiny">Attribution for verified public releases in this workspace.</p>${credits.map(r=>`<section class="settings-section"><h3>${esc(r.name)} · ${esc(r.release)}</h3><p>${esc(r.acknowledgment)}</p><p class="tiny">${esc(r.conditions)}</p><p class="tiny">${esc(r.citation)}</p><div class="action-row">${[['terms_url','Provider terms'],['citation_url','Citation']].filter(([key])=>r[key]?.startsWith('https://')).map(([key,label])=>`<a href="${esc(r[key])}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`).join('')}</div><small>${esc(r.files.join(' · '))}</small></section>`).join('')||'<p>Verified public releases will appear here when available.</p>'}`;}
 if(tab==='general')html+=`<div class="settings-grid"><section class="settings-section"><div class="eyebrow">IDENTITY</div><h3>${esc(state.user.email)}</h3><p>${esc(state.user.role)} · authenticated research workspace</p><button id="logoutButton" class="button quiet">Sign out</button></section><section class="settings-section"><div class="eyebrow">APPEARANCE</div><div class="field"><label>Colour theme</label><select id="themeChoice"><option value="dark" ${s.theme==='dark'?'selected':''}>Dark · navy</option><option value="light" ${s.theme==='light'?'selected':''}>Light</option></select></div><p>Choose your workspace appearance.</p></section></div><section class="settings-section"><div class="eyebrow">CANVAS PERFORMANCE</div><h3>Measure this device.</h3><p>Measure 500 nodes and 2,000 edges. Your workflow is restored afterward.</p><button id="benchmarkButton" class="button quiet">Run renderer benchmark</button><pre id="benchmarkResult" class="mono"></pre></section><details><summary>Research use & validation</summary><p>Research use only. Clinical certification, independent compliance review and representative full-scale assay validation are not established.</p></details>`;
 if(tab==='vault'){const entries=await api('/vault');html+=`<div class="note">Keys are encrypted, scoped to selected nodes and never displayed again.</div><section class="settings-section"><div class="eyebrow">ADD OR ROTATE A CREDENTIAL</div><div class="settings-grid"><div class="field"><label>Provider / licence</label><select id="vaultProvider">${['franklin','oncokb','customapi','cosmic','openai','sentieon','dragen','hgmd','annovar'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Label</label><input id="vaultLabel" placeholder="Lab research account" autocomplete="off"></div></div><div class="field"><label>API key or licence token</label><input id="vaultValue" type="password" autocomplete="new-password" placeholder="Encrypted on save; never displayed again"></div><div class="field"><label>Allowed tools</label><select id="vaultTools" multiple size="5" aria-label="Tools allowed to use this credential"></select><input id="vaultBindings" type="hidden" value="franklin"><small>Choose only the tools permitted to use this credential.</small></div><button id="saveVault" class="button primary">Encrypt & save credential</button></section><h3>Stored credentials</h3>${entries.length?entries.map(v=>`<div class="vault-card"><span class="node-glyph">♧</span><div><strong>${esc(v.label)}</strong><small>${esc(v.provider)} · ${esc(v.mode)} · v${v.version} · ${v.revoked?'REVOKED':'active'}</small><small>Bound to ${esc(v.bindings.join(', ')||'no nodes')}</small></div><button data-check-secret="${v.id}" class="quiet" ${v.revoked?'disabled':''}>Check</button><button data-rotate-secret="${v.id}" class="quiet">Rotate</button><button data-revoke-secret="${v.id}" class="quiet danger" ${v.revoked?'disabled':''}>Revoke</button></div>`).join(''):'<p>No credentials stored. Public sample workflows do not need any.</p>'}`;state.vault=entries;}
 openModal('Workspace settings',html,'NGS STUDIO');if(retentionData)bindRetention(retentionData);modalClick('[data-settings-tab]',(e,b)=>showSettings(b.dataset.settingsTab));modalClick('#logoutButton',async()=>{await api('/logout',{method:'POST',body:{}});closeModal();location.reload();});$('#themeChoice')?.addEventListener('change',guarded(async e=>{await api('/settings',{method:'PATCH',body:{theme:e.target.value}});document.body.classList.toggle('light',e.target.value==='light');canvas.invalidate();}));modalClick('#benchmarkButton',async(e,b)=>{b.disabled=true;b.textContent='Measuring 500 nodes…';closeModal();const original=state.graph,view={...canvas.view},temporary={name:'Performance probe',nodes:[],edges:[]};for(let i=0;i<500;i++)temporary.nodes.push({id:'bench'+i,tool:'utility.gather',x:(i%25)*225,y:Math.floor(i/25)*135,params:{},resources:{}});for(let i=1;i<500;i++)for(let j=1;j<=4;j++)if(i>=j)temporary.edges.push({id:'be'+i+'_'+j,source:'bench'+(i-j),sourcePort:'collection',target:'bench'+i,targetPort:'items'});for(let j=10;j<20;j++)temporary.edges.push({id:'extra'+j,source:'bench0',sourcePort:'collection',target:'bench'+j,targetPort:'items'});canvas.setGraph(temporary,state.nodes);canvas.fit();await new Promise(r=>setTimeout(r,50));const result=await canvas.benchmark();canvas.setGraph(original,state.nodes);canvas.view=view;canvas.invalidate();$('#zoomLabel').textContent=Math.round(view.k*100)+'%';openModal('Canvas benchmark',`<p>Actual measurements from this browser. Edges with no matching port are omitted by the renderer, so this probe reports both submitted and drawable edges.</p><pre class="mono">${esc(JSON.stringify({...result,drawn_edges:temporary.edges.filter(e=>state.defs.get(temporary.nodes.find(n=>n.id===e.source).tool).outputs.some(p=>p.key===e.sourcePort)&&state.defs.get(temporary.nodes.find(n=>n.id===e.target).tool).inputs.some(p=>p.key===e.targetPort)).length},null,2))}</pre>`,'PERFORMANCE');});
 if($('#vaultProvider')){selectVaultBindings($('#vaultProvider').value);$('#vaultProvider').addEventListener('change',e=>selectVaultBindings(e.target.value));}modalClick('#saveVault',async()=>{await api('/vault',{method:'POST',body:{provider:$('#vaultProvider').value,label:$('#vaultLabel').value,value:$('#vaultValue').value,bindings:$('#vaultBindings').value.split(',').map(x=>x.trim()).filter(Boolean)}});$('#vaultValue').value='';toast('Credential encrypted and stored');await showSettings('vault');});modalClick('[data-check-secret]',async(e,b)=>{const r=await api('/vault/'+b.dataset.checkSecret+'/check',{method:'POST',body:{}});toast(r.message,r.state==='rejected');});modalClick('[data-rotate-secret]',(e,b)=>{const s=state.vault.find(x=>x.id===b.dataset.rotateSecret);selectVaultBindings(s.provider,s.bindings);$('#vaultLabel').value=s.label;$('#vaultValue').value='';$('#vaultValue').focus();});modalClick('[data-revoke-secret]',async(e,b)=>{await api('/vault/'+b.dataset.revokeSecret+'/revoke',{method:'POST',body:{}});toast('Platform binding revoked. Rotate/revoke the token at the provider as well.');showSettings('vault');});}
function updateBackend(){$('#backendLabel').innerHTML='<span class="status-dot"></span>AWS · us-east-1';}
async function requestTier(){openModal('Request an entitlement review','<p>Tier changes in this deployment are reviewed by the workspace administrator.</p><div class="field"><label>Requested tier</label><select id="requestedTier"><option>academic</option><option>pro</option><option>enterprise</option></select></div><div class="field"><label>Institution and intended usage</label><textarea id="tierReason" rows="4"></textarea></div><button id="sendTierRequest" class="button primary">Submit review request</button>','TRUST CONTROL PLANE');modalClick('#sendTierRequest',async()=>{await api('/tier-requests',{method:'POST',body:{tier:$('#requestedTier').value,reason:$('#tierReason').value}});closeModal();toast('Review request recorded for the administrator');});}
async function resolveNodeImage(spec){if(state.user.role!=='admin')throw new Error('Image publication requires an administrator.');openModal('Resolve an execution image',`<p>Resolve the actual registry manifest, inspect its immutable digest, then approve it for this node. This step does not pull image layers or start compute.</p><div class="field"><label>OCI / BioContainer image</label><input id="imageReference" value="${esc(spec.image||'')}"></div><button id="resolveImage" class="button primary">Resolve manifest</button><div id="imageResult"></div>`,'RUNTIME PUBLICATION');modalClick('#resolveImage',async()=>{const r=await api('/tools/'+spec.id+'/resolve-image',{method:'POST',body:{image:$('#imageReference').value}});$('#imageResult').innerHTML=`<div class="note mono">${esc(r.image)}</div><p>${esc(r.source)}. Review code, database rights and the security profile before approval.</p><button id="approveImage" class="button primary">Approve this digest</button>`;modalClick('#approveImage',async()=>{const settings=await api('/settings');await api('/settings',{method:'PATCH',body:{image_approvals:{...settings.image_approvals,[spec.id]:r.image}}});toast('Immutable image approved and audited');closeModal();});});}
async function showAdmin(){const r=await api('/admin');openModal('Platform operations',`<div class="action-row"><button id="adminRetention" class="button quiet">Retention controls</button></div><div class="metric-grid" style="grid-template-columns:repeat(4,1fr)"><div class="metric"><strong>${r.runs.filter(x=>['running','queued','cancelling'].includes(x.state)).length}</strong><span>Active / queued runs</span></div><div class="metric"><strong>${r.users.length}</strong><span>Workspace accounts</span></div><div class="metric"><strong>${duration(r.users.reduce((a,u)=>a+u.reserved_seconds,0))}</strong><span>Reserved CPU</span></div><div class="metric"><strong>${bytes(r.storage_bytes)}</strong><span>Published artifact bytes</span></div></div><div class="settings-section"><div class="action-row"><h3>Emergency admission control</h3><span class="spacer"></span><button id="globalFreeze" class="button danger">Freeze & stop all pipelines</button><button id="globalUnfreeze" class="button quiet">Reopen admission</button></div><div class="field"><label>Audit reason for administrative actions</label><input id="adminReason" placeholder="Required · incident, quota review or approved request"></div></div><h3>Accounts</h3><details class="admin-create"><summary>Create Explore account</summary><div class="field-grid"><label class="field">Email<input id="newUserEmail" type="email" autocomplete="off"></label><label class="field">Initial password<input id="newUserPassword" type="password" autocomplete="new-password" minlength="12"></label></div><p class="tiny">Uses the audit reason above. Compute funding is assigned separately.</p><button id="createUser" class="button primary">Create account</button></details><table class="table"><thead><tr><th>Account</th><th>Access</th><th>Used / reserved</th><th>Actions</th></tr></thead><tbody>${r.users.map(u=>`<tr><td>${esc(u.email)}<small style="display:block">${esc(u.role)} · ${u.frozen?'frozen':'active'}</small></td><td>${esc(u.entitlements?.label||'Explore')}</td><td>${duration(u.used_seconds)} / ${duration(u.reserved_seconds)}</td><td><button class="quiet" data-fund-user="${esc(u.id)}">Allowance</button><button class="quiet danger" data-freeze-user="${u.id}" data-frozen="${u.frozen?'0':'1'}">${u.frozen?'Release':'Freeze'}</button>${u.id!==state.user.id?`<button class="quiet danger" data-remove-user="${esc(u.id)}">Remove access</button>`:''}</td></tr>`).join('')}</tbody></table><h3 style="margin-top:24px">Live pipeline monitor</h3>${r.runs.length?`<table class="table"><thead><tr><th>Run</th><th>State</th><th>Reserved / used</th><th>Action</th></tr></thead><tbody>${r.runs.slice(0,25).map(x=>`<tr><td class="mono">${esc(x.id.slice(-12))}</td><td class="state-${esc(x.state)}">${esc(x.state)}</td><td>${duration(x.reserved)} / ${duration(x.used)}</td><td>${['running','queued','cancelling'].includes(x.state)?`<button class="quiet danger" data-kill="${x.id}">Terminate</button>`:'Terminal'}</td></tr>`).join('')}</tbody></table>`:'<p>No executions have been submitted.</p>'}<div class="settings-section" style="margin-top:22px"><h3>Node quarantine</h3><div class="field-grid"><select id="quarantineTool">${state.nodes.map(n=>`<option value="${n.id}">${esc(n.name)}</option>`).join('')}</select><div class="action-row"><button id="quarantineNode" class="button danger">Quarantine</button><button id="releaseNode" class="button quiet">Release</button></div></div>${r.quarantine.map(q=>`<div class="note warning">${esc(q.tool_id)} · ${esc(q.reason)}</div>`).join('')}</div><h3>Audit chain · ${r.audit_verification.valid?'verified':'FAILED'}</h3><p>${r.audit_verification.records} records · independent WORM anchoring is a separate production control.</p><div class="mono note">${esc(r.audit_verification.head||'')}</div><table class="table"><thead><tr><th>Time</th><th>Action</th><th>Resource</th><th>Hash</th></tr></thead><tbody>${r.audit.slice(0,100).map(a=>`<tr><td class="audit-time">${new Date(a.event.time*1000).toLocaleString()}</td><td class="audit-action">${esc(a.event.action)}</td><td class="mono">${esc(a.event.resource.slice(-18))}</td><td class="mono">${a.hash.slice(0,16)}</td></tr>`).join('')}</tbody></table>`,'ADMIN · AUDITED OPERATIONS');modalClick('#adminRetention',showRetentionAdmin);const reason=()=>{const v=$('#adminReason').value.trim();if(v.length<10)throw new Error('Provide an audit reason of at least 10 characters.');return v;};modalClick('#createUser',async(e,b)=>{const email=$('#newUserEmail').value.trim(),password=$('#newUserPassword').value;if(!email||password.length<12)throw new Error('Enter an email and a password of at least 12 characters.');b.disabled=true;try{await api('/admin/users',{method:'POST',body:{email,password,reason:reason()}});$('#newUserPassword').value='';toast('Explore account created');await showAdmin();}finally{b.disabled=false;}});modalClick('[data-fund-user]',(e,b)=>{$('#cloudOperationsButton').dataset.selectedUser=b.dataset.fundUser;$('#cloudOperationsButton').click();});modalClick('[data-remove-user]',async(e,b)=>{await api('/admin/users/'+encodeURIComponent(b.dataset.removeUser)+'/remove',{method:'POST',body:{reason:reason()}});toast('Account access removed; results and audit history retained');await showAdmin();});modalClick('[data-freeze-user]',async(e,b)=>{await api('/admin/users/'+b.dataset.freezeUser,{method:'POST',body:{reason:reason(),frozen:b.dataset.frozen==='1'}});toast('Workspace freeze state updated');showAdmin();});modalClick('[data-kill]',async(e,b)=>{await api('/admin/runs/'+b.dataset.kill+'/kill',{method:'POST',body:{reason:reason()}});toast('Termination requested');showAdmin();});for(const [id,frozen]of [['globalFreeze',true],['globalUnfreeze',false]])modalClick('#'+id,async()=>{await api('/admin/freeze',{method:'POST',body:{frozen,reason:reason()}});toast(frozen?'Admission frozen; cancellation dispatched':'Admission reopened');showAdmin();});for(const[id,release]of [['quarantineNode',false],['releaseNode',true]])modalClick('#'+id,async()=>{await api('/admin/quarantine',{method:'POST',body:{tool_id:$('#quarantineTool').value,reason:reason(),release}});toast('Node release state updated');await loadCatalogue();showAdmin();});}
async function publishTool(){openModal('Bring your own tool.',`<p>Publish a digest-pinned container with explicit data contracts. It runs through the same resource, quota and governance checks. Publishing is restricted to the workspace owner in this deployment.</p><div class="settings-grid"><div class="field"><label>Tool name</label><input id="customName" placeholder="My validated analysis"></div><div class="field"><label>Code / asset rights</label><select id="customLicense"><option>FOSS</option><option>Academic</option><option>Commercial BYOL</option><option>Review required</option></select></div></div><div class="field"><label>Immutable OCI image</label><input id="customImage" placeholder="registry/repository@sha256:…"></div><div class="field"><label>Command · whitespace / quoted arguments</label><input id="customCommand" placeholder="samtools flagstat -O json {in.data}"><small>Use {in.data} for the input file and {work} for /work. Commands execute as argv, never a host shell. A tool must write its declared output file.</small></div><div class="settings-grid"><div class="field"><label>Input type</label><select id="customInput">${['ANY','FASTQ','BAM','SORTED_BAM','INDEXED_BAM','VCF','INDEXED_VCF','FASTA','BED','H5AD'].map(t=>`<option>${t}</option>`).join('')}</select></div><div class="field"><label>Output type</label><select id="customOutput">${['REPORT','VCF','BAM','SORTED_BAM','INDEXED_BAM','FASTQ','BED','H5AD','ANY'].map(t=>`<option>${t}</option>`).join('')}</select></div></div><div class="field"><label>Output file · relative to /work</label><input id="customFile" placeholder="result.json"></div><div class="field"><label class="toggle-label">Capture stdout to the output file<input id="customStdout" type="checkbox" checked></label></div><div class="field"><label>Scoped BYOL licence file · optional</label><select id="customCredential"><option value="">No secret required</option><option>sentieon</option><option>dragen</option><option>hgmd</option><option>annovar</option></select><small>Use {secret.file} in the command. The credential must be explicitly bound to the published node in Vault. API keys stay in provider brokers.</small></div><button id="publishCustom" class="button primary">Publish reviewed tool contract</button>`,'UNIVERSAL CONTAINER');modalClick('#publishCustom',async()=>{const type=$('#customOutput').value;const r=await api('/tools/publish',{method:'POST',body:{name:$('#customName').value,image:$('#customImage').value,license:$('#customLicense').value,command_line:$('#customCommand').value,capture_stdout:$('#customStdout').checked,secret_delivery:$('#customCredential').value?{kind:'file',provider:$('#customCredential').value}:null,inputs:[{key:'data',type:$('#customInput').value}],outputs:[{key:'result',type}],output_files:{result:{file:$('#customFile').value,type}}}});await loadCatalogue();addNode(r.id);closeModal();toast('Tool contract published');});}
$('#settingsButton').onclick=guarded(()=>showSettings());$('#dataCreditsButton').onclick=guarded(()=>showSettings('credits'));$('#vaultButton').onclick=guarded(()=>showSettings('vault'));$('#tierButton').onclick=guarded(()=>showSettings('trust'));$('#adminButton').onclick=guarded(showAdmin);$('#publishButton').onclick=guarded(publishTool);$('#profileButton').onclick=guarded(()=>showSettings('general'));
let authSignup=false;function showAuth(setup=false){authSignup=setup;$('#authTitle').textContent=setup?'Your research workspace.':'Welcome back.';$('#authDescription').textContent=setup?'Create your research account. Explore includes bounded sample workflows; Research Pro requires a funded administrator allowance.':'Sign in to continue your pipelines, datasets and execution history.';$('#authSubmit').textContent=setup?'Create workspace':'Sign in';$('#authToggle').textContent=setup?'Already have an account? Sign in':'Create a research account';$('#authError').hidden=true;$('#authToggle').hidden=state.signupAllowed===false; if(state.signupAllowed===false&&!setup)$('#authDescription').textContent='Sign in with your administrator-created account.';if(!$('#authModal').open)$('#authModal').showModal();}
$('#authModal').addEventListener('cancel',e=>e.preventDefault());$('#authToggle').onclick=()=>showAuth(!authSignup);$('#authForm').onsubmit=async e=>{e.preventDefault();$('#authSubmit').disabled=true;try{const f=new FormData(e.target),r=await api('/auth/'+(authSignup?'signup':'login'),{method:'POST',body:{email:f.get('email'),password:f.get('password'),otp:f.get('otp')||''}});state.user=r.user;state.csrf=r.csrf;$('#authModal').close();e.target.reset();await initialize();}catch(error){$('#authError').textContent=error.message;$('#authError').hidden=false;}finally{$('#authSubmit').disabled=false;}};
async function loadCatalogue(){const c=await api('/catalog');state.nodes=c.nodes;state.templates=c.templates;state.dependencies=c.dependencies||[];state.capabilities=c.capabilities;state.demo=c.demo;document.body.classList.toggle('hosted-demo',!!c.demo?.enabled);$('#sourceLink').hidden=!c.demo?.self_host_url;if(c.demo?.self_host_url)$('#sourceLink').href=c.demo.self_host_url;state.defs=new Map(c.nodes.map(n=>[n.id,n]));$('#catalogCount').textContent=c.nodes.length;renderCategories();renderLibrary();canvas.setGraph(state.graph,state.nodes);}
async function initialize(){await refreshSession();renderUsageStatus(await api('/account/usage'));await loadCatalogue();state.settings=await api('/settings');document.body.classList.toggle('light',state.settings.theme==='light');updateBackend();await refreshAssets();renderLibrary();const graphs=await api('/graphs');if(graphs.length){const g=await api('/graphs/'+graphs[0].id);if(g.body.nodes.every(n=>state.defs.has(n.tool)))replaceGraph(g.body,g.id,g.revision);else replaceGraph(state.templates[0].graph);}else replaceGraph(state.templates[0].graph);$('#connectionStatus').textContent='Workspace connected';renderBottom();if(location.pathname==='/settings')showSettings();if(location.pathname==='/admin'&&state.user.role==='admin')showAdmin();}
window.addEventListener('keydown',e=>{if(e.defaultPrevented||e.altKey||/INPUT|SELECT|TEXTAREA/.test(document.activeElement.tagName)||document.activeElement.isContentEditable||$('#modal').open||$('#authModal').open)return;if(e.key==='/'){e.preventDefault();panels.reveal('left',true);}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelection();}if((e.metaKey||e.ctrlKey)&&e.key==='z'){e.preventDefault();e.shiftKey?redo():undo();}if((e.metaKey||e.ctrlKey)&&e.key==='s'){e.preventDefault();saveGraph();}if(e.key==='Escape')selectNode(null);if(e.key.toLowerCase()==='f')canvas.fit({overview:e.shiftKey});if(state.selected&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const n=state.graph.nodes.find(n=>n.id===state.selected);remember();n.x+=e.key==='ArrowRight'?10:e.key==='ArrowLeft'?-10:0;n.y+=e.key==='ArrowDown'?10:e.key==='ArrowUp'?-10:0;changed(false);}});
const extensions=installExtensions({api,state,esc,toast,guarded,openModal,closeModal,loadCatalogue,addNode,showSettings,showArtifact});
const bootstrap=await api('/bootstrap');state.signupAllowed=bootstrap.signup_allowed;state.deployment=bootstrap.deployment;state.demo=bootstrap.demo;document.body.classList.toggle('hosted-demo',!!bootstrap.demo?.enabled);if(bootstrap.user){state.user=bootstrap.user;state.csrf=bootstrap.csrf;await guarded(initialize)();}else showAuth(bootstrap.setup_required);
