window.ngsDiagnostics={benchmark:()=>canvas.benchmark(),graphCounts:()=>({nodes:state.graph.nodes.length,edges:state.graph.edges.length}),version:'1.0.0'};



async function pickAsset(node,key){
 const spec=state.defs.get(node.tool);
 openModal('Choose a cloud dataset','<div class="search-wrap" style="margin:0 0 15px"><input id="assetPickerSearch" type="search" placeholder="Database, assembly, release or filename…" autofocus></div><div id="assetPickerResults"></div>','DATA BINDING');
 let timer,serial=0;
 const search=async(offset=0)=>{const attempt=++serial,term=$('#assetPickerSearch')?.value||'',params=new URLSearchParams({primary:'1',node:spec.id,q:term,offset:String(offset),limit:'40'}),result=await api('/assets?'+params),holder=$('#assetPickerResults');if(!holder||attempt!==serial)return;const matches=result.assets.filter(a=>acceptsAsset(spec,a));holder.innerHTML=assetPageMarkup(result)+(matches.map(a=>`<div class="asset-choice"><button class="outline-row" data-pick-asset="${esc(a.id)}"><span>▱</span><span>${esc(assetPresentation(a).title)}<small>${esc(a.format)} · ${bytes(a.bytes)}</small></span><span class="spacer"></span>＋</button>${assetIdentityMarkup(a)}</div>`).join('')||'<p>No compatible cloud datasets.</p>');holder.querySelectorAll('[data-asset-page]').forEach(b=>b.onclick=guarded(()=>search(Number(b.dataset.assetPage))));holder.querySelectorAll('[data-pick-asset]').forEach(b=>b.onclick=()=>{const a=matches.find(x=>x.id===b.dataset.pickAsset);remember();node.params[key]=a.id;if(node.tool==='reference.asset'&&a.assembly)node.params.assembly=a.assembly;state.assetSelection.set(a.id,a);changed(false);closeModal();toast('Cloud dataset bound');});};
 $('#assetPickerSearch').oninput=()=>{clearTimeout(timer);timer=setTimeout(guarded(()=>search()),220);};await search();$('#assetPickerSearch')?.focus();
}
